/* exec argv[1] with stdout = write end of a pipe whose read end is already closed */
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
int main(int argc, char** argv){
  int fd[2];
  if (pipe(fd)) { perror("pipe"); return 2; }
  close(fd[0]);                 /* reader gone, deterministically */
  if (dup2(fd[1], 1) < 0) { perror("dup2"); return 2; }
  close(fd[1]);
  execv(argv[1], &argv[1]);
